<?php
session_start();

// --- 1. CONFIGURATION ---
// Connect directly to the SQLite database generated by the python scripts
$sqlite_db = '../largeDB.db';

// SHA-256 hash for the password "admin123"
$hardcoded_hash = '240be518fabd2724ddb6f04eeb1da5967448d7e831c08c8fa822809f74c720a9';

// --- 2. AUTHENTICATION LOGIC ---
$login_error = false;

// Handle login form submission
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['password'])) {
    if (hash('sha256', $_POST['password']) === $hardcoded_hash) {
        $_SESSION['authenticated'] = true;
        // Redirect to avoid form resubmission on refresh
        header("Location: " . $_SERVER['PHP_SELF']); 
        exit;
    } else {
        $login_error = true;
    }
}

// --- 3. API ENDPOINTS (Returns JSON to the map) ---
// If the user requests data but isn't logged in, block them.
if (isset($_GET['action'])) {
    header('Content-Type: application/json');
    
    if (empty($_SESSION['authenticated'])) {
        http_response_code(401);
        echo json_encode(['error' => 'Unauthorized']);
        exit;
    }

    try {
        $pdo = new PDO("sqlite:" . $sqlite_db);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        if ($_GET['action'] === 'get_tags') {
            $stmt = $pdo->query("SELECT name, hashed_key FROM tags");
            echo json_encode($stmt->fetchAll(PDO::FETCH_ASSOC));
            exit;
        }

        if ($_GET['action'] === 'get_locations' && isset($_GET['key'])) {
            // Query the trips table with all its new calculated columns
            $stmt = $pdo->prepare("SELECT latitude, longitude, time, velocity, distance, motion_state, time_spent, transport_mode, elevation FROM trips WHERE hashed_key = ? ORDER BY time ASC");
            $stmt->execute([$_GET['key']]);
            echo json_encode($stmt->fetchAll(PDO::FETCH_ASSOC));
            exit;
        }

        if ($_GET['action'] === 'get_places') {
            $stmt = $pdo->query("SELECT latitude, longitude, significance, unique_tags, is_overnight FROM places");
            echo json_encode($stmt->fetchAll(PDO::FETCH_ASSOC));
            exit;
        }
    } catch (PDOException $e) {
        http_response_code(500);
        echo json_encode(['error' => $e->getMessage()]);
        exit;
    }
}

// --- 4. HTML FRONTEND (Served only if authenticated) ---
?>
<!DOCTYPE html>
